# Filter items containing '{substring}'
items = {items}
substring = '{substring}'
case_sensitive = {case_sensitive}
if not case_sensitive:
    substring = substring.lower()
    filtered = [item for item in items if substring in (item.lower() if isinstance(item, str) else str(item).lower())]
else:
    filtered = [item for item in items if substring in (item if isinstance(item, str) else str(item))]
return filtered
